def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append(('op', c))
            i += 1
            continue
        raise ValueError("Unexpected character: " + c)

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] in ('+', '-'):
                advance()
                rhs = parse_term()
                if tok[1] == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] in ('*', '/'):
                advance()
                rhs = parse_factor()
                if tok[1] == '*':
                    val = val * rhs
                else:
                    if (val < 0) != (rhs < 0):
                        val = -(abs(val) // abs(rhs))
                    else:
                        val = abs(val) // abs(rhs)
            else:
                break
        return val

    def parse_factor():
        neg_count = 0
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] == '-':
                advance()
                neg_count += 1
            else:
                break
        val = parse_primary()
        if neg_count % 2 == 1:
            val = -val
        return val

    def parse_primary():
        tok = advance()
        if tok[0] == 'num':
            return tok[1]
        if tok[0] == 'op' and tok[1] == '(':
            val = parse_expr()
            close = advance()
            if not (close[0] == 'op' and close[1] == ')'):
                raise ValueError("Expected closing parenthesis")
            return val
        raise ValueError("Unexpected token: " + str(tok))

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

